    memset(grid, 0, sizeof(grid));

    int row, col, size;

    while (scanf("%d %d %d", &row, &col, &size) == 3) {
        if (size == 1) {
            // Small: only the cell itself
            if (row >= 0 && row < 10 && col >= 0 && col < 10)
                grid[row][col]++;
        } else if (size == 2) {
            // Medium: cell + 4 neighbors (cross)
            int dr[] = {0, -1, 1, 0, 0};
            int dc[] = {0, 0, 0, -1, 1};
            for (int i = 0; i < 5; i++) {
                int nr = row + dr[i];
                int nc = col + dc[i];
                if (nr >= 0 && nr < 10 && nc >= 0 && nc < 10)
                    grid[nr][nc]++;
            }
        } else if (size == 3) {
            // Large: 3x3 area
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    int nr = row + dr;
                    int nc = col + dc;
                    if (nr >= 0 && nr < 10 && nc >= 0 && nc < 10)
                        grid[nr][nc]++;
                }
            }
        }
    }

    int zeros = 0, maxDensity = 0;
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            if (grid[i][j] == 0) zeros++;
