import java.util.Scanner;

public class InkDrops {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] grid = new int[10][10];

        while (sc.hasNextInt()) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            int size = sc.nextInt();

            if (size == 1) {
                // Small drop: affects only the center cell
                if (x >= 0 && x < 10 && y >= 0 && y < 10) {
                    grid[x][y]++;
                }
            } else if (size == 2) {
                // Medium drop: affects center and adjacent cells (Manhattan distance ≤ 1)
                for (int dx = -1; dx <= 1; dx++) {
                    for (int dy = -1; dy <= 1; dy++) {
                        int nx = x + dx;
                        int ny = y + dy;
                        if (nx >= 0 && nx < 10 && ny >= 0 && ny < 10) {
                            grid[nx][ny]++;
                        }
                    }
                }
            } else if (size == 3) {
                // Large drop: affects all cells with Chebyshev distance ≤ 1 from center
                for (int dx = -1; dx <= 1; dx++) {
                    for (int dy = -1; dy <= 1; dy++) {
                        int nx = x + dx;
                        int ny = y + dy;
                        if (nx >= 0 && nx < 10 && ny >= 0 && ny < 10) {
                            grid[nx][ny]++;
                        }
                    }
                }
                // Also affects cells at Manhattan distance 2 along axes
                int[][] extra = {{-2,0}, {2,0}, {0,-2}, {0,2}};
                for (int[] d : extra) {
                    int nx = x + d[0];
                    int ny = y + d[1];
                    if (nx >= 0 && nx < 10 && ny >= 0 && ny < 10) {
                        grid[nx][ny]++;
                    }
                }
                // And the four diagonal cells at distance (1,1) are already covered by the 3x3 block,
                // but large also includes the cells at distance 2 diagonally
                int[][] diagExtra = {{-2,-2}, {-2,2}, {2,-2}, {2,2}};
                for (int[] d : diagExtra) {
                    int nx = x + d[0];
                    int ny = y + d[1];
                    if (nx >= 0 && nx < 10 && ny >= 0 && ny < 10) {
                        grid[nx][ny]++;
                    }
                }
            }
        }

        int zeroCount = 0;
        int maxDensity = 0;
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < 10; j++) {
                if (grid[i][j] == 0) zeroCount++;
                if (grid[i][j] > maxDensity) maxDensity = grid[i][j];
            }
        }

        System.out.println(zeroCount);
        System.out.println(maxDensity);
        sc.close();
    }
}

