int main() {
    vector<vector<int>> grid(10, vector<int>(10, 0));
    int x, y, size;

    while (cin >> x >> y >> size) {
        if (size == 1) { // Small
            if (x - 1 >= 0) grid[y][x - 1]++;
            if (x + 1 < 10) grid[y][x + 1]++;
            if (y - 1 >= 0) grid[y - 1][x]++;
            if (y + 1 < 10) grid[y + 1][x]++;
        } else if (size == 2) { // Medium
            for (int dy = -1; dy <= 1; dy++) {
                for (int dx = -1; dx <= 1; dx++) {
                    int nx = x + dx, ny = y + dy;
                    if (nx >= 0 && nx < 10 && ny >= 0 && ny < 10) {
                        grid[ny][nx]++;
                    }
                }
            }
        } else if (size == 3) { // Large
            for (int dy = -2; dy <= 2; dy++) {
                for (int dx = -2; dx <= 2; dx++) {
                    int nx = x + dx, ny = y + dy;
                    if (nx >= 0 && nx < 10 && ny >= 0 && ny < 10) {
                        if (abs(dx) + abs(dy) <= 2) {
                            grid[ny][nx]++;
                        }
                    }
                }
            }
        }
    }

    int zeroCount = 0;
    int maxDensity = 0;
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < 10; j++) {
            if (grid[i][j] == 0) zeroCount++;
            maxDensity = max(maxDensity, grid[i][j]);
        }
    }

    cout << zeroCount << "\n" << maxDensity << endl;
    return 0;
}

