int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    const int N = 10;
    int n;
    cin >> n;

    vector<vector<int>> grid(N, vector<int>(N, 0));

    for (int i = 0; i < n; ++i) {
        int x, y, s;
        cin >> x >> y >> s;

        // Apply a square splash of radius (s-1) centered at (x, y)
        int r = s - 1;
        for (int dx = -r; dx <= r; ++dx) {
            for (int dy = -r; dy <= r; ++dy) {
                int nx = x + dx;
                int ny = y + dy;
                if (0 <= nx && nx < N && 0 <= ny && ny < N) {
                    grid[nx][ny]++;
                }
            }
        }
    }

    int zeroCount = 0, maxDensity = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (grid[i][j] == 0) zeroCount++;
            maxDensity = max(maxDensity, grid[i][j]);
        }
    }

    cout << zeroCount << "\n" << maxDensity << "\n";
    return 0;
}

