import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    idx = 1

    grid = [[0] * 10 for _ in range(10)]

    for _ in range(n):
        x = int(data[idx]); y = int(data[idx + 1]); size = int(data[idx + 2])
        idx += 3

        # Center cell always increases
        if 0 <= x < 10 and 0 <= y < 10:
            grid[y][x] += 1

        # Medium and Large affect orthogonally adjacent cells
        if size >= 2:
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 10 and 0 <= ny < 10:
                    grid[ny][nx] += 1

        # Large also affects diagonal adjacent cells
        if size >= 3:
            for dx, dy in [(-1, -1), (-1, 1), (1, -1), (1, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 10 and 0 <= ny < 10:
                    grid[ny][nx] += 1

    zero_count = 0
    max_density = 0

    for row in grid:
        for v in row:
            if v == 0:
                zero_count += 1
